  "invariants": [
    {
      "invariant": "Activation de dsi-fpt et dcp-fpt observable.",
      "statut": "respecte",
      "motif": "Les activations de dsi-fpt et dcp-fpt sont couvertes par l’attestation mécanique de lecture intégrale et ordonnée ; leurs lectures sont observables dans la trace.",
      "trace_lines": [6, 22]
    },
    {
      "invariant": "BASCULE dcp-fpt avant tout volet de marché confié à DCP ; BASCULE DirFi et DPO avant leurs volets.",
